var SERVO={sg90:{name:"SG90 micro",tq:1.8,m:9,cost:400},mg90s:{name:"MG90S metal",tq:2.2,m:13,cost:600},mg996:{name:"MG996R heavy",tq:11,m:55,cost:1100},ds3218:{name:"DS3218 pro",tq:25,m:60,cost:1400}};
